class Solution {
public:
    int maximizeSquareArea(int m, int n, vector<int>& hFences, vector<int>& vFences) {
        const long long MOD = 1000000007;
        hFences.push_back(1);
        hFences.push_back(m);
        vFences.push_back(1);
        vFences.push_back(n);
        sort(hFences.begin(), hFences.end());
        sort(vFences.begin(), vFences.end());

        unordered_set<int> hDiffs;
        int hs = (int)hFences.size();
        for (int i = 0; i < hs; i++) {
            for (int j = i + 1; j < hs; j++) {
                hDiffs.insert(hFences[j] - hFences[i]);
            }
        }

        long long best = 0;
        int vs = (int)vFences.size();
        for (int i = 0; i < vs; i++) {
            for (int j = i + 1; j < vs; j++) {
                int d = vFences[j] - vFences[i];
                if (hDiffs.count(d) && d > best) {
                    best = d;
                }
            }
        }

        if (best == 0) return -1;
        return (int)((best * best) % MOD);
    }
};
